using sv_947c07f9f9974e8baacff9a5e1fc474a.Client.Models;
using sv_947c07f9f9974e8baacff9a5e1fc474a.Client.Services;

namespace sv_947c07f9f9974e8baacff9a5e1fc474a.Services;

public class ServerShipmentService : ShipmentServiceBase
{
    private static readonly Dictionary<string, ShipmentDetails> Shipments = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new ShipmentDetails(
            "TRK-1001",
            "In Transit",
            "Memphis, TN",
            new DateTime(2026, 7, 2),
            [
                new StatusUpdate(new DateTime(2026, 6, 23, 8, 0, 0), "Picked Up", "Los Angeles, CA"),
                new StatusUpdate(new DateTime(2026, 6, 24, 14, 30, 0), "Departed Facility", "Los Angeles, CA"),
                new StatusUpdate(new DateTime(2026, 6, 25, 6, 15, 0), "Arrived at Hub", "Memphis, TN"),
            ]),
        ["TRK-1002"] = new ShipmentDetails(
            "TRK-1002",
            "Delivered",
            "New York, NY",
            new DateTime(2026, 6, 20),
            [
                new StatusUpdate(new DateTime(2026, 6, 17, 9, 0, 0), "Picked Up", "Chicago, IL"),
                new StatusUpdate(new DateTime(2026, 6, 18, 11, 0, 0), "In Transit", "Columbus, OH"),
                new StatusUpdate(new DateTime(2026, 6, 19, 16, 45, 0), "Out for Delivery", "New York, NY"),
                new StatusUpdate(new DateTime(2026, 6, 20, 10, 30, 0), "Delivered", "New York, NY"),
            ]),
        ["TRK-1003"] = new ShipmentDetails(
            "TRK-1003",
            "Processing",
            "Seattle, WA",
            new DateTime(2026, 7, 5),
            [
                new StatusUpdate(new DateTime(2026, 6, 25, 17, 0, 0), "Label Created", "Seattle, WA"),
            ]),
    };

    public override async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct = default)
    {
        await Task.Delay(1500, ct);
        Shipments.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@implements IAsyncDisposable
@inject ShipmentServiceBase ShipmentService
@inject ILogger<Shipment> Logger

@using sv_947c07f9f9974e8baacff9a5e1fc474a.Client.Models
@using sv_947c07f9f9974e8baacff9a5e1fc474a.Client.Services

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h1>Shipment Tracking</h1>

@if (error is not null)
{
    <div class="alert alert-danger">
        <p>@error</p>
        <button class="btn btn-outline-danger" @onclick="LoadAsync">Retry</button>
    </div>
}
else if (shipment is null)
{
    @if (isLoading)
    {
        <p><em>Loading shipment @TrackingNumber…</em></p>
    }
    else
    {
        <p>Shipment <strong>@TrackingNumber</strong> was not found.</p>
    }
}
else
{
    @if (isLoading)
    {
        <p><em>Refreshing…</em></p>
    }

    <dl>
        <dt>Tracking Number</dt>
        <dd>@shipment.TrackingNumber</dd>
        <dt>Status</dt>
        <dd>@shipment.Status</dd>
        <dt>Location</dt>
        <dd>@shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@shipment.EstimatedDelivery.ToShortDateString()</dd>
    </dl>

    <h2>Status History</h2>
    <table class="table">
        <thead>
            <tr>
                <th>Time</th>
                <th>Status</th>
                <th>Location</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in shipment.StatusUpdates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = default!;

    private CancellationTokenSource? cts;
    private string? loadedTrackingNumber;
    private ShipmentDetails? shipment;
    private bool isLoading;
    private string? error;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(TrackingNumber, loadedTrackingNumber, StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        loadedTrackingNumber = TrackingNumber;
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }

        cts = new CancellationTokenSource();
        var cancellationToken = cts.Token;

        error = null;
        isLoading = true;

        try
        {
            var result = await ShipmentService.GetShipmentAsync(TrackingNumber, cancellationToken);
            shipment = result;
        }
        catch (OperationCanceledException ex) when (!cancellationToken.IsCancellationRequested)
        {
            Logger.LogWarning(ex, "Request timed out for shipment {TrackingNumber}", TrackingNumber);
            error = "The request timed out. Please try again.";
        }
        catch (OperationCanceledException)
        {
            // Self-cancellation (disposal or parameter change) — let ComponentBase handle it.
            throw;
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load shipment {TrackingNumber}", TrackingNumber);
            error = "Something went wrong loading this shipment. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

